     const elements = stripe.elements();
     const cardElement = elements.create('card');  // Mount this to a <div> in your form
     cardElement.mount('#card-element');

     // When form is submitted:
     stripe.createPaymentMethod({
       type: 'card',
       card: cardElement,
       billing_details: {
         name: 'John Doe',  // Optional, but recommended
       },
     }).then((result) => {
       if (result.error) {
         console.error(result.error.message);
       } else {
         // Send result.paymentMethod.id to your server
         fetch('/create-customer', {
           method: 'POST',
           headers: { 'Content-Type': 'application/json' },
           body: JSON.stringify({ paymentMethodId: result.paymentMethod.id }),
         });
       }
     });
     ```

   - **Server-Side (e.g., in Node.js using the Stripe SDK):**
     - Receive the token/payment method ID from the client.
     - Create the customer and attach the payment method.

