    // to associate with your internal user record.
    console.log('Successfully created Stripe customer:', customer.id);

    res.json({
      message: 'Customer created successfully!',
      customerId: customer.id,
    });

  } catch (error) {
    console.error('Error creating customer:', error);
    // The error message is "must provide source or customer id"
    // This happens if the `payment_method` field is missing or invalid in this call.
    res.status(500).json({ error: { message: error.message } });
  }
});

app.listen(3000, () => console.log('Server running on port 3000'));
```

### Summary of the Fix

1.  **On your Frontend:** Stop sending raw card details to your server. Use Stripe.js and Elements to call `stripe.createPaymentMethod()`.
2.  **Frontend to Backend:** Send the resulting `paymentMethod.id` (which starts with `pm_...`) to your server.
3.  **On your Backend:** In your `stripe.customers.create()` call, use the `payment_method` parameter with the ID you received from the frontend.

By following this flow, you ensure that sensitive card data never hits your server, which drastically simplifies your PCI compliance requirements and is the secure, intended way to use the Stripe API.

